mapper.select:
        select to_pid from bus_rel where DELFLAG_ = '1' and from_type = 'PSN' and to_type = 'PSN' and rel_category = 'A' and rel_category_sub in ('1','2','3','4') and from_pid = #{pid}
        union
        select from_pid from bus_rel where DELFLAG_ = '1' and from_type = 'PSN' and to_type = 'PSN' and rel_category = 'A' and rel_category_sub in ('1','2','3','4') and to_pid = #{pid}

        select to_pid as pid,to_type as type from bus_rel where DELFLAG_ = '1' and rel_category = 'C' and rel_category_sub in ('10','14') and from_pid = #{pid} and from_type = #{type}
        union
        select from_pid as pid,from_type as type from bus_rel where DELFLAG_ = '1' and rel_category = 'D' and rel_category_sub = '18' and to_pid = #{pid} and to_type = #{type}

select * from bus_rel r
where 1=1

    and r.from_memo = #{fromMemo}


    and r.from_identify_number = #{fromIdentifyNumber}


    and r.rel_psn_org = #{relPsnOrg}


    and r.to_Memo = #{toMemo}


    and r.to_identify_number = #{toIdentifyNumber}


    and r.approval_status = #{approvalStatus}


    and r.isValid = #{isValid}


    and r.item_description = #{itemDescription}


    and r.to_type = #{toType}


    and r.to_pid = #{toPid}


    and r.DELFLAG_ = #{delflag}

ORDER BY MODIFIED_TIME_ DESC,CREATED_TIME_ DESC

select * from bus_rel
    where from_identify_number = #{fromIdentifyNumber}
        and to_identify_number = #{toIdentifyNumber}
        and DELFLAG_ = '1'

SELECT rel.PID , rel.PID_UNIQUE, rel.TO_PID , rel.TO_TYPE , toInfo.REL_NAME TO_NAME, rel.FROM_PID, rel.FROM_TYPE, fromInfo.REL_NAME FROM_NAME, rel.SHAREHOLDING_RATIO , rel.REL_CATEGORY_SUB FROM ( SELECT br.PID , 'A' || br.pid PID_UNIQUE, br.TO_PID , br.TO_TYPE , br.FROM_PID, br.FROM_TYPE, br.SHAREHOLDING_RATIO , br.REL_PSN_ORG REL_CATEGORY_SUB FROM BUS_REL br WHERE br.APPROVAL_STATUS = '6' AND DELFLAG_ = '1' ) rel INNER JOIN ( SELECT brp.PID , 'PSN' REL_TYPE, brp.NAME_ REL_NAME, brp.IDENTIFY_NUMBER FROM BUS_REL_PSN brp WHERE brp.DELFLAG_ = '1' UNION SELECT bro.PID , 'ORG' REL_TYPE, bro.ORG_NAME REL_NAME, bro.UNISC_CODE IDENTIFY_NUMBER FROM BUS_REL_ORG bro WHERE bro.DELFLAG_ = '1' UNION SELECT brp.PID , 'PRO' REL_TYPE, brp.PRO_NAME REL_NAME, brp.PRO_PROVIDER IDENTIFY_NUMBER FROM BUS_REL_PRO brp WHERE brp.DELFLAG_ = '1' ) toInfo ON toInfo.PID = rel.TO_PID AND toInfo.REL_TYPE = rel.TO_TYPE INNER JOIN ( SELECT brp.PID , 'PSN' REL_TYPE, brp.NAME_ REL_NAME, brp.IDENTIFY_NUMBER FROM BUS_REL_PSN brp WHERE brp.DELFLAG_ = '1' UNION SELECT bro.PID , 'ORG' REL_TYPE, bro.ORG_NAME REL_NAME, bro.UNISC_CODE IDENTIFY_NUMBER FROM BUS_REL_ORG bro WHERE bro.DELFLAG_ = '1' UNION SELECT brp.PID , 'PRO' REL_TYPE, brp.PRO_NAME REL_NAME, brp.PRO_PROVIDER IDENTIFY_NUMBER FROM BUS_REL_PRO brp WHERE brp.DELFLAG_ = '1' ) fromInfo ON fromInfo.PID = rel.FROM_PID AND fromInfo.REL_TYPE = rel.FROM_TYPE
and rel.TO_PID = #{param.toPid}
and rel.TO_TYPE = #{param.toType}
and rel.FROM_PID = #{param.fromPid}
and rel.FROM_TYPE = #{param.fromType}
